import {photoStories} from './content.js?v=final21';
const KEY='umanga-photo-stories-v1';
const limits={story:1800,location:100,date:80,settings:150};
export function validateStories(value,photos){
 if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Choose a photo stories export.');
 const allowed=new Set(photos.map(p=>p.id)),result={};
 for(const [id,entry] of Object.entries(value)){
  if(!allowed.has(id))continue;
  if(!entry||typeof entry!=='object'||Array.isArray(entry))throw new Error('Invalid story entry.');
  result[id]={};for(const [field,max] of Object.entries(limits)){const text=entry[field]??'';if(typeof text!=='string'||text.length>max)throw new Error('A story field is invalid or too long.');result[id][field]=text;}
 }return result;
}
export function initPhotoStories({photos,lightbox}){
 let drafts={},current=photos[0],editing=photos[0],lastFocus=null,storageOK=true;
 try{drafts=validateStories(JSON.parse(localStorage.getItem(KEY)||'{}'),photos);}catch{storageOK=false;}
 const area=document.createElement('div');area.className='photo-story';area.innerHTML='<div class="story-actions"><button type="button" data-story-toggle aria-expanded="false" aria-controls="frame-story" hidden>Behind this frame +</button><button type="button" data-story-edit>Write this photo’s story</button></div><section id="frame-story" hidden><p class="story-prose"></p><dl class="story-details"></dl></section>';
 lightbox.append(area);
 const modal=document.createElement('dialog');modal.id='photo-story-editor';modal.setAttribute('aria-labelledby','story-editor-title');modal.dataset.storyUi='';
 modal.innerHTML=`<header class="story-editor-header"><div><span class="meta">YOUR WORDS / YOUR FRAMES</span><h2 id="story-editor-title">Behind the frame.</h2></div><button type="button" data-story-done>Done ×</button></header><p class="story-editor-note">Drafts stay in this browser. Download your stories and copy them into the photoStories list in content.js to publish them on the site.</p><div class="story-editor-layout"><div><img class="story-preview" alt=""><label>Photograph<select data-story-photo></select></label></div><form class="story-fields"><label>The story<textarea name="story" rows="6" maxlength="1800" placeholder="What happened outside the frame? What made you stop?"></textarea></label><div class="story-field-pair"><label>Place <small>optional</small><input name="location" maxlength="100"></label><label>When <small>optional</small><input name="date" maxlength="80"></label></div><label>Camera settings or a note <small>optional</small><input name="settings" maxlength="150"></label><p role="status" data-story-status></p></form></div><footer class="story-editor-footer"><button type="button" data-story-download>Download stories ↓</button><label class="story-import">Import stories<input type="file" accept="application/json,.json" data-story-import></label></footer>`;
 document.body.append(modal);const select=modal.querySelector('select'),form=modal.querySelector('form'),status=modal.querySelector('[data-story-status]'),toggle=area.querySelector('[data-story-toggle]'),panel=area.querySelector('#frame-story');
 photos.forEach(photo=>{const option=document.createElement('option');option.value=photo.id;option.textContent=photo.title;select.append(option);});
 function entry(photo){return drafts[photo.id]??photoStories[photo.id]??{};}
 function render(reset=false){const data=entry(current),has=Object.values(data).some(v=>v?.trim());toggle.hidden=!has;if(reset||!has){panel.hidden=true;toggle.setAttribute('aria-expanded','false');}toggle.textContent=panel.hidden?'Behind this frame +':'Close the story −';area.querySelector('[data-story-edit]').textContent=has?'Edit this photo’s story':'Write this photo’s story';area.querySelector('.story-prose').textContent=data.story||'';area.querySelector('.story-prose').hidden=!data.story?.trim();const dl=area.querySelector('dl');dl.replaceChildren();for(const [key,label] of [['location','PLACE'],['date','WHEN'],['settings','NOTES']]){if(!data[key]?.trim())continue;const group=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=data[key];group.append(dt,dd);dl.append(group);}}
 function persist(){try{localStorage.setItem(KEY,JSON.stringify(drafts));storageOK=true;}catch{storageOK=false;}status.textContent=storageOK?'Saved in this browser.':'Browser storage unavailable. Download your stories before leaving.';render();}
 function fill(photo){editing=photo;select.value=photo.id;const data=entry(photo);for(const key of Object.keys(limits))form.elements.namedItem(key).value=data[key]||'';const img=modal.querySelector('img');img.src=photo.thumb||photo.src;img.alt=photo.alt;status.textContent=storageOK?'Changes save automatically in this browser.':'Browser storage unavailable. Download your stories before leaving.';}
 function open(photo=current){lastFocus=document.activeElement;fill(photo);modal.showModal();document.body.classList.add('modal-open');form.elements.namedItem('story').focus();}
 toggle.addEventListener('click',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));render();});
 area.querySelector('[data-story-edit]').addEventListener('click',()=>open());
 select.addEventListener('change',()=>fill(photos.find(p=>p.id===select.value)||photos[0]));
 form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',()=>{drafts[editing.id]=Object.fromEntries(Object.entries(limits).map(([key,max])=>[key,form.elements.namedItem(key).value.slice(0,max)]));persist();});
 modal.querySelector('[data-story-done]').addEventListener('click',()=>modal.close());modal.addEventListener('close',()=>{document.body.classList.toggle('modal-open',!!document.querySelector('dialog[open]'));lastFocus?.focus();});
 modal.querySelector('[data-story-download]').addEventListener('click',()=>{const stories=validateStories({...photoStories,...drafts},photos);const url=URL.createObjectURL(new Blob([JSON.stringify({format:'umanga-photo-stories',version:1,stories},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='umanga-photo-stories.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Download requested. Use the stories in content.js to publish them on the site.';});
 modal.querySelector('[data-story-import]').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw new Error('Please choose a stories file smaller than 1 MB.');const data=JSON.parse(await file.text());if(data.format!=='umanga-photo-stories'||data.version!==1)throw new Error('Choose a photo stories export.');const imported=validateStories(data.stories,photos);if(!Object.keys(imported).length)throw new Error('No matching photographs found.');drafts={...drafts,...imported};persist();fill(editing);status.textContent=storageOK?'Stories imported and saved in this browser.':'Imported in memory. Download before leaving.';}catch(error){status.textContent=error.message||'Could not import that file.';}e.target.value='';});
 const launcher=document.createElement('button');launcher.type='button';launcher.className='story-editor-launch';launcher.textContent='Edit photo stories ↗';launcher.dataset.storyUi='';launcher.addEventListener('click',()=>open(current));document.querySelector('.orbit-footer').append(launcher);
 return {show(photo){current=photo;render(true);},open};
}
